window.StrictDoc.search.nodesByMid = {"1":{"MID":"d9314f4c8d6c4838831a2069cd130e9d","UID":"IRS001","TITLE":"Cell bus signals","STATEMENT":"Cell_IronAir output bus SHALL include at minimum: Voltage_V, Current_A, SOC, Temperature_K, H2_Rate_mol_s, H2_Volume_m3, FaradaicEfficiency.\n","_LINK":"IRS001"},"2":{"MID":"e52af96e70fd48ecb7206fbba058317f","UID":"IRS002","TITLE":"Pack bus signals","STATEMENT":"Pack_IronAir SHALL aggregate Voltage_V (series), Current_A (parallel), Energy_Wh, SOC, H2_Volume_m3, Temperature_K.\n","_LINK":"IRS002"},"3":{"MID":"71eebb979ea142fabe91de7f8a9706fb","UID":"IRS003","TITLE":"Plant schedule inputs","STATEMENT":"Plant_BESS_Schedule SHALL accept PowerSchedule_W(t) and optional GridVoltage_pu(t), GridFrequency_Hz(t) for ride-through injection.\n","_LINK":"IRS003"},"4":{"MID":"a209b4de460640cca16e5656225000dc","UID":"IRS004","TITLE":"Monitor outputs","STATEMENT":"DER_RideThrough_Monitors and Standards_Assert_* SHALL output boolean Pass flags and violation counters for voltage, frequency, thermal, and H2 envelopes.\n","_LINK":"IRS004"},"5":{"MID":"0bb8a57633844783be52f59584d00058","UID":"IRS005","TITLE":"Data dictionary API","STATEMENT":"lib_IronAir_init SHALL create or update lib_IronAir.sldd with section Design Data entries for IronAir.Cell, IronAir.Stack, IronAir.Module, IronAir.Pack, IronAir.Plant, IronAir.Standards, IronAir.MockData.\n","_LINK":"IRS005"},"6":{"MID":"9ef4ca461a02452faeec3f49c6db2f09","UID":"SDD001","TITLE":"Discretization","STATEMENT":"Each 1D domain uses Nx control volumes. State vectors are length Nx (or species×Nx). Spatial operators use second-order central differences with Neumann/Dirichlet boundaries as documented in src/ ironair_*_ode.m files.\n","_LINK":"SDD001"},"7":{"MID":"53724afa317649be91a24a3c13b6d767","UID":"SDD002","TITLE":"Cell voltage equation","STATEMENT":"Cell voltage is V = E_eq(c,T) - eta_metal - eta_air - I*R_elec where eta_air selects ORR (discharge, I>0 convention discharge positive) or OER (charge).\n","_LINK":"SDD002"},"8":{"MID":"b528f8be070d4640a11cc2f57d3b7b34","UID":"SDD003","TITLE":"HER kinetics","STATEMENT":"H2 evolution uses Tafel/Butler-Volmer form i_H2 = i0_H2 * exp(alpha_H2*F*eta_H2/(R*T)) gated by metal overpotential; n_dot_H2 = i_H2*A/(2*F); Faradaic efficiency eta_F = 1 - I_H2/(abs(I)+eps).\n","_LINK":"SDD003"},"9":{"MID":"a9c8d5b7e01b4795a5945d473ed66dce","UID":"SDD004","TITLE":"Solver guidance","STATEMENT":"Recommended solvers: ode15s or ode23tb; RelTol 1e-4; AbsTol 1e-6 (concentration) / 1e-3 (temperature). Documented in model ConfigSet of demos.\n","_LINK":"SDD004"},"10":{"MID":"7c8312a3d3f047dbb1adce57796872a1","UID":"SDD005","TITLE":"Multi-rate strategy","STATEMENT":"Fast electrical signals (V, I, ride-through) use continuous or small fixed step; thermal uses continuous with larger thermal mass; plant schedule uses slow exogenous From Workspace profiles. Rate Transition blocks separate domains in plant demo.\n","_LINK":"SDD005"},"11":{"MID":"0514b9b59b4b4fddbf89ce9ec9e026c1","UID":"SDD006","TITLE":"Mask and requirement citation","STATEMENT":"Each masked library block documentation pane SHALL cite relevant SSS/SRS UIDs.\n","_LINK":"SDD006"},"12":{"MID":"b311f5d0b3c94f0ba7914f9a28a58bfb","UID":"SRS001","TITLE":"Project identity","STATEMENT":"The project SHALL provide a first-principles continuous-time Simulink model of an aqueous alkaline iron-air battery energy storage system (BESS) under the project name iron-air-modeling.\n","RATIONALE":"Establishes system scope and naming for all subordinate requirements.\n","_LINK":"SRS001"},"13":{"MID":"f4e35150290041c2ad8705290d26d17c","UID":"SRS002","TITLE":"Chemistry and cell architecture","STATEMENT":"The model SHALL represent aqueous alkaline iron-air chemistry with a metal electrode, a dedicated ORR electrode, a dedicated OER electrode, and a static flooded KOH electrolyte domain separating the oxygen electrodes from the metal electrode.\n","_LINK":"SRS002"},"14":{"MID":"eb5f88dd2c9947b6ad5b06fd10a92bee","UID":"SRS003","TITLE":"Spatial fidelity","STATEMENT":"Electrode and electrolyte domains SHALL be modeled in one spatial dimension (1D) with finite-volume / control-volume discretization.\n","_LINK":"SRS003"},"15":{"MID":"dc9a29e0e301444da53bc5d5d96f73b5","UID":"SRS004","TITLE":"Hydrogen evolution","STATEMENT":"The model SHALL include parasitic hydrogen evolution (HER) on the metal electrode and SHALL expose H2 molar rate, cumulative H2 volume, and Faradaic efficiency loss.\n","_LINK":"SRS004"},"16":{"MID":"bb3aaeb2e0054039ae7d92f2bc7a7ab8","UID":"SRS005","TITLE":"Hierarchical composition","STATEMENT":"The system SHALL compose Cell, Stack, Module, Pack, and Plant levels from reusable library components without duplicating physics at higher levels.\n","_LINK":"SRS005"},"17":{"MID":"f3e9420fca91486984405502b7a233e1","UID":"SRS006","TITLE":"Multi-day energy arbitrage","STATEMENT":"The plant-level model SHALL support continuous simulation of 24 h to 100 h energy arbitrage power/energy schedules.\n","_LINK":"SRS006"},"18":{"MID":"c8e63a1f90764d6aa824ce2e8a34ba56","UID":"SRS007","TITLE":"Multi-rate timescales","STATEMENT":"The system SHALL support electrical, thermal, and multi-day SOC timescales with multi-rate / co-simulation guidance so each component can be simulated and tested independently.\n","_LINK":"SRS007"},"19":{"MID":"5c16f42834c14f39a76ec9b30b4e012a","UID":"SRS008","TITLE":"Parameter management","STATEMENT":"All model parameters SHALL be defined in lib_IronAir_init.m and stored in the Simulink Data Dictionary lib_IronAir.sldd.\n","_LINK":"SRS008"},"20":{"MID":"6cec2d5511104b5e8a3688ac57047e31","UID":"SRS009","TITLE":"Library packaging","STATEMENT":"First-principles components SHALL be packaged in a single Simulink library file lib_IronAir.slx with masks on subsystems where appropriate.\n","_LINK":"SRS009"},"21":{"MID":"9043d072781f409fb9d4aed5a08bc574","UID":"SRS010","TITLE":"Requirements management","STATEMENT":"All project requirements SHALL be managed with StrictDoc under requirements/ using MIL-STD-498 document types (SRS, SSS, SDD, IRS, TP, TD). Doorstop SHALL NOT be used.\n","_LINK":"SRS010"},"22":{"MID":"57d8db84ceeb438a9f5f30da7bafa317","UID":"SRS011","TITLE":"IEEE 1547-2018 compliance intent","STATEMENT":"The project SHALL document and implement plant-level Simulink monitors consistent with IEEE 1547-2018 interconnection and ride-through behavioral envelopes (voltage and frequency) for DER/ESS plant interface studies. Switching-level inverter models are out of scope.\n","COMMENT":"Simulink linkage: DER_RideThrough_Monitors block.\n","_LINK":"SRS011"},"23":{"MID":"310432b8faad4bf18d3f4ecc3b058c65","UID":"SRS012","TITLE":"IEEE 1547.9-2022 compliance intent","STATEMENT":"The project SHALL document ESS interconnection guidance per IEEE 1547.9-2022 as plant interconnection requirements and associated Simulink assertion monitors for energy storage plant studies.\n","_LINK":"SRS012"},"24":{"MID":"7e8942aababc47c596ec9c9caea1dd5a","UID":"SRS013","TITLE":"UL 1741 compliance intent","STATEMENT":"The project SHALL implement plant-interface behavioral interconnection envelopes consistent with UL 1741 (without PWM/switching PCS detail) via Simulink monitors linked to this requirement.\n","_LINK":"SRS013"},"25":{"MID":"6a4d8766ec404cf6aa66e932eabbb264","UID":"SRS014","TITLE":"UL 9540 compliance intent","STATEMENT":"The project SHALL implement ESS safety envelope monitors consistent with UL 9540 for thermal limits and abnormal operating conditions exposable by the physics model.\n","_LINK":"SRS014"},"26":{"MID":"cfe1c1df9f1c41c6a90af59ecf74b4d8","UID":"SRS015","TITLE":"NFPA 855 compliance intent","STATEMENT":"The project SHALL implement monitors related to NFPA 855 for thermal and hydrogen accumulation quantities produced by the physics model.\n","_LINK":"SRS015"},"27":{"MID":"5410ff2fe2234d7b9e5305a601e1e181","UID":"SRS016","TITLE":"Validation data","STATEMENT":"The project SHALL provide estimated synthetic mock cell charge/discharge curves under data/mock/ for regression testing.\n","_LINK":"SRS016"},"28":{"MID":"141311e17213497791a74af0af476817","UID":"SRS017","TITLE":"Pure Simulink continuous ODEs","STATEMENT":"Physics SHALL be implemented as pure Simulink continuous-time ODE systems (no Simscape custom components in v1).\n","_LINK":"SRS017"},"29":{"MID":"fefab5c845004940ada0d5cbc404683e","UID":"SSS001","TITLE":"Library file","STATEMENT":"The implementation SHALL provide lib_IronAir.slx containing masked first-principles subsystems.\n","_LINK":"SSS001"},"30":{"MID":"593cd066754a4746b6382d4348f59648","UID":"SSS002","TITLE":"Continuous-time ODEs","STATEMENT":"Atomic physics blocks SHALL implement continuous first-order ODEs using Simulink Integrator blocks driven by explicit dy/dt equations (no S-Functions), suitable for variable-step stiff solvers (ode15s / ode23tb class).\n","_LINK":"SSS002"},"31":{"MID":"ddb6cd4974554ec5b940867cfa245087","UID":"SSS003","TITLE":"Electrolyte_1D block","STATEMENT":"lib_IronAir SHALL include Electrolyte_1D implementing 1D KOH transport (Fick + migration approximation) and ohmic drop between oxygen-electrode and metal-electrode domains.\n","_LINK":"SSS003"},"32":{"MID":"665e9626cca348b0933213544a56c035","UID":"SSS004","TITLE":"Metal_Electrode_1D block","STATEMENT":"lib_IronAir SHALL include Metal_Electrode_1D implementing Fe / Fe(OH)2 / Fe3O4 utilization via Faraday's law and Butler-Volmer kinetics.\n","_LINK":"SSS004"},"33":{"MID":"4e865b9a9c5d4dfeb81ea6d764359fc9","UID":"SSS005","TITLE":"ORR_Electrode_1D block","STATEMENT":"lib_IronAir SHALL include ORR_Electrode_1D for oxygen reduction with O2 mass-transport limitation.\n","_LINK":"SSS005"},"34":{"MID":"e937d6a3484e4e52a643cfead456a4ce","UID":"SSS006","TITLE":"OER_Electrode_1D block","STATEMENT":"lib_IronAir SHALL include OER_Electrode_1D for oxygen evolution on a dedicated electrode during charge.\n","_LINK":"SSS006"},"35":{"MID":"af8bee6b664340bea7ccfadfac3221f4","UID":"SSS007","TITLE":"H2_Evolution block","STATEMENT":"lib_IronAir SHALL include H2_Evolution computing parasitic HER rate, cumulative H2, and Faradaic efficiency loss.\n","_LINK":"SSS007"},"36":{"MID":"07a02f27b8364354b0d5522bf6086886","UID":"SSS008","TITLE":"Thermal_Node_1D block","STATEMENT":"lib_IronAir SHALL include Thermal_Node_1D coupling Joule and reaction heat into temperature ODEs that feed Arrhenius kinetics.\n","_LINK":"SSS008"},"37":{"MID":"a7abe404d21445f28db5dc4e93b4adfa","UID":"SSS009","TITLE":"Cell composition","STATEMENT":"Cell_IronAir SHALL compose Electrolyte_1D, Metal_Electrode_1D, ORR_Electrode_1D, OER_Electrode_1D, H2_Evolution, and Thermal_Node_1D via library links.\n","_LINK":"SSS009"},"38":{"MID":"787d25682bdf40a483bc1d28706ff7f7","UID":"SSS010","TITLE":"Stack Module Pack composition","STATEMENT":"Stack_IronAir, Module_IronAir, and Pack_IronAir SHALL aggregate lower-level library blocks for series/parallel scaling and bus aggregation only.\n","_LINK":"SSS010"},"39":{"MID":"9f047f4d2ba049e9ad01ffa509265e29","UID":"SSS011","TITLE":"Plant schedule block","STATEMENT":"Plant_BESS_Schedule SHALL accept exogenous plant power/energy schedules spanning 24-100 h and apply a simple PCS efficiency gain (no switching inverter).\n","_LINK":"SSS011"},"40":{"MID":"27ed0816918f4257a55a6264896ff98d","UID":"SSS012","TITLE":"DER ride-through monitors","STATEMENT":"DER_RideThrough_Monitors SHALL assert IEEE 1547-2018 / UL 1741 style voltage and frequency ride-through envelopes at the plant interface.\n","_LINK":"SSS012"},"41":{"MID":"512135c3276946be8598e98034d3e6df","UID":"SSS013","TITLE":"Standards assert blocks","STATEMENT":"Standards_Assert blocks SHALL monitor UL 9540, NFPA 855, and IEEE 1547.9-2022 envelopes for thermal, H2, SOC, and power quantities where physics exists.\n","_LINK":"SSS013"},"42":{"MID":"793cd0ebf25c4f528afdfd361252d143","UID":"SSS014","TITLE":"Init and data dictionary","STATEMENT":"lib_IronAir_init.m SHALL populate nested IronAir.* structs and write lib_IronAir.sldd; models SHALL reference the dictionary rather than free-floating base workspace policy after init.\n","_LINK":"SSS014"},"43":{"MID":"66a2e825f9cf4853966dde98cfa3e62e","UID":"SSS015","TITLE":"Per-block testability","STATEMENT":"Each atomic library block SHALL have a MATLAB unit harness under tests/ verifying conservation and/or mock-data regression.\n","_LINK":"SSS015"},"44":{"MID":"2f55dfd1bb47486b9a0abf3806378150","UID":"SSS016","TITLE":"Mock cell curves","STATEMENT":"generate_mock_cell_curves SHALL write synthetic V-I-t and coulombic efficiency data under data/mock/ loaded by lib_IronAir_init.\n","_LINK":"SSS016"},"45":{"MID":"e776451f53074269af5e623f86cf3be1","UID":"TD001","TITLE":"Electrolyte mass conservation","STATEMENT":"tests/test_Electrolyte_1D.m SHALL verify KOH moles conserved within 1e-6 relative under zero-flux boundaries and zero source.\n","_LINK":"TD001"},"46":{"MID":"857e852cfc454dd89d902218bfc1c667","UID":"TD002","TITLE":"H2 evolution positivity","STATEMENT":"tests/test_H2_Evolution.m SHALL verify H2 rate >= 0 and Faradaic efficiency in [0,1] for cathodic overpotentials.\n","_LINK":"TD002"},"47":{"MID":"f40035c9face4083ac3e2bf430cbed3a","UID":"TD003","TITLE":"Metal utilization bounds","STATEMENT":"tests/test_Metal_Electrode_1D.m SHALL keep solid-phase utilization in [0,1].\n","_LINK":"TD003"},"48":{"MID":"de4415f94fd541518cfb73ddc61d3134","UID":"TD004","TITLE":"ORR OER polarity","STATEMENT":"tests/test_ORR_OER_1D.m SHALL verify ORR current sign on discharge and OER on charge.\n","_LINK":"TD004"},"49":{"MID":"92bff8c2a8ee40f1a3c67988856fb944","UID":"TD005","TITLE":"Thermal stability","STATEMENT":"tests/test_Thermal_Node_1D.m SHALL verify temperature remains finite and increases under positive heat input.\n","_LINK":"TD005"},"50":{"MID":"dbf5b180a1ac4b2b87a445a0179b391f","UID":"TD006","TITLE":"Cell mock regression","STATEMENT":"tests/test_Cell_IronAir_mock.m SHALL compare simulated V(t) to data/mock/mock_discharge_VI.mat within TP003 RMSE bound.\n","_LINK":"TD006"},"51":{"MID":"edbd92b82e4544c390a3b6c68a6aa383","UID":"TD007","TITLE":"Pack aggregation","STATEMENT":"tests/test_Pack_Aggregation.m SHALL verify series voltage scaling and parallel current scaling.\n","_LINK":"TD007"},"52":{"MID":"75643c91f0344051bf99fc553e2448fb","UID":"TD008","TITLE":"Plant ride-through","STATEMENT":"tests/test_Plant_RideThrough.m SHALL inject voltage/frequency excursions and assert monitor Pass/Fail matches IEEE 1547-style envelopes in IronAir.Standards.\n","_LINK":"TD008"},"53":{"MID":"d78b4d997fe44225b9d64b238f824397","UID":"TP001","TITLE":"Test levels","STATEMENT":"Testing SHALL include (1) atomic MATLAB unit tests per physics block, (2) cell integration / mock V-I regression, (3) stack/pack aggregation checks, (4) plant 24-100 h arbitrage with ride-through monitors.\n","_LINK":"TP001"},"54":{"MID":"936473669ea2407c930517ddfa3f6663","UID":"TP002","TITLE":"Tooling","STATEMENT":"Unit tests SHALL use the MATLAB Unit Testing Framework under tests/ and be invoked via `make test`.\n","_LINK":"TP002"},"55":{"MID":"a94b288f3d404bfc8262bd780e17b2af","UID":"TP003","TITLE":"Mock-data acceptance","STATEMENT":"Cell voltage RMSE against mock discharge curves SHALL be within 50 mV for the reference constant-current case after parameter lock.\n","_LINK":"TP003"},"56":{"MID":"f04431f044b64d14ae0ebbd2ea0e4cf8","UID":"TP004","TITLE":"Requirements validation","STATEMENT":"`make strictdoc-validate` SHALL pass before release commits that change requirements.\n","_LINK":"TP004"}};
